 g.add=href=>g.links.push({getAttribute:attr=>{assert.equal(attr,'href');return href;},closest:sel=>{assert.equal(sel,'details');return g;}});
 hrefs.forEach(g.add); return g;
}
function tree(groups){ return {ownerDocument:doc,dataset:{streelingBase:'/learn/'},querySelectorAll:sel=>sel==='a[href]'?groups.flatMap(g=>g.querySelectorAll(sel)):groups.flatMap(function flatten(g){return[g,...g.children.flatMap(flatten)];})}; }
