const dialogMusic=group(['/learn/fr/streeling/music/','/learn/fr/streeling/music/mus-001/']);
const navs=[tree([ancestor]),tree([dialogMusic])];
doc.querySelectorAll=sel=>{assert.equal(sel,'[data-streeling-nav]');return navs;};
