const {streelingLinkIdentity}=await import('./src/scripts/streeling-nav-counts.mjs?adversarial');
assert.equal(music.badges[0].textContent,'(1)');assert.equal(empty.badges[0].textContent,'(0)');assert.equal(ancestor.badges.length,0);assert.equal(dialogMusic.badges[0].textContent,'(1)');
music.add('/learn/fr/streeling/music/mus-002/');
for(let i=0;i<1000;i++)handlers.get('astro:page-load')();
