music.links=music.links.slice(0,1);handlers.get('astro:page-load')();assert.equal(music.badges[0].textContent,'(0)');
for(const href of ['https://external.test/learn/fr/streeling/music/mus-001/','/learn-evil/fr/streeling/music/mus-001/','/learn/fr/streeling/music/journal/','/learn/fr/streeling/music/overview/','/learn/fr/streeling/music/index/','/learn/fr/streeling/music/mus-001/lesson/'])assert.equal(streelingLinkIdentity(href,{baseUrl:'/learn/',pageUrl:doc.baseURI}),null,href);
